def evaluate(expr: str) -> float:
    """
    Evaluate an arithmetic expression without using eval, exec, compile, or ast.
    Supports integers, decimals, +, -, *, /, parentheses, and unary minus.
    Raises ZeroDivisionError for division by zero.
    Raises ValueError for malformed input.
    """
    if not expr or not expr.strip():
        raise ValueError("Empty expression")

    # Tokenize
    tokens = []
    i = 0
    n = len(expr)
    while i < n:
        ch = expr[i]
        if ch.isspace():
            i += 1
            continue
        if ch in '+-*/()':
            tokens.append(ch)
            i += 1
        elif ch.isdigit() or ch == '.':
            # Parse number
            j = i
            has_dot = False
            while j < n and (expr[j].isdigit() or expr[j] == '.'):
                if expr[j] == '.':
                    if has_dot:
                        raise ValueError(f"Invalid number at position {j}")
                    has_dot = True
                j += 1
            num_str = expr[i:j]
            if num_str == '.':
                raise ValueError(f"Invalid number at position {i}")
            try:
                tokens.append(float(num_str))
            except ValueError:
                raise ValueError(f"Invalid number at position {i}")
            i = j
        else:
            raise ValueError(f"Unknown character '{ch}' at position {i}")

    if not tokens:
        raise ValueError("Empty expression")

    # Parser using recursive descent
    # Grammar:
    # expression = term (('+' | '-') term)*
    # term = factor (('*' | '/') factor)*
    # factor = ('+' | '-') factor | primary
    # primary = NUMBER | '(' expression ')'

    pos = [0]  # Use list to allow mutation in nested functions

    def peek():
        if pos[0] < len(tokens):
            return tokens[pos[0]]
        return None

    def consume():
        if pos[0] >= len(tokens):
            raise ValueError("Unexpected end of expression")
        tok = tokens[pos[0]]
        pos[0] += 1
        return tok

    def parse_expression():
        result = parse_term()
        while peek() in ('+', '-'):
            op = consume()
            right = parse_term()
            if op == '+':
                result += right
            else:
                result -= right
        return result

    def parse_term():
        result = parse_factor()
        while peek() in ('*', '/'):
            op = consume()
            right = parse_factor()
            if op == '*':
                result *= right
            else:
                if right == 0:
                    raise ZeroDivisionError("Division by zero")
                result /= right
        return result

    def parse_factor():
        tok = peek()
        if tok == '+':
            consume()
            return parse_factor()
        elif tok == '-':
            consume()
            return -parse_factor()
        else:
            return parse_primary()

    def parse_primary():
        tok = peek()
        if tok is None:
            raise ValueError("Unexpected end of expression")
        if isinstance(tok, float):
            consume()
            return tok
        elif tok == '(':
            consume()
            result = parse_expression()
            if peek() != ')':
                raise ValueError("Missing closing parenthesis")
            consume()
            return result
        else:
            raise ValueError(f"Unexpected token {tok}")

    result = parse_expression()

    # Check that all tokens were consumed
    if pos[0] != len(tokens):
        raise ValueError(f"Unexpected token at position {pos[0]}")

    return result
